UPDATE recording_analysis_outbox
SET next_attempt_at = #{leaseUntil,typeHandler=com.ssafy.eyesonu.common.persistence.mybatis.UtcInstantTypeHandler}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND claim_token = #{claimToken}

UPDATE recording_analysis_outbox
SET status = 'PUBLISHED',
    claim_token = NULL,
    published_at = #{publishedAt,typeHandler=com.ssafy.eyesonu.common.persistence.mybatis.UtcInstantTypeHandler}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND claim_token = #{claimToken}
